-- ===================== options.sql =====================
-- Store — product options + security hardening (run in Supabase → SQL Editor). Safe to run again.
-- Adds the options column, teaches place_order to price them,
-- and tightens abuse limits (coupon guessing, order flooding, oversized input). Prices are always computed here.


alter table public.products add column if not exists options jsonb not null default '[]'::jsonb;


-- Each order records when the customer accepted the terms & declaration, and which version (shown on the invoice)
alter table public.orders add column if not exists terms_accepted_at timestamptz;
alter table public.orders add column if not exists terms_version text;

-- Coupons: optional usage cap
alter table public.coupons add column if not exists max_uses int;
alter table public.coupons add column if not exists used int not null default 0;

-- a used-up coupon reads as invalid
create or replace function public.check_coupon(p_code text) returns public.coupons
language sql stable security definer set search_path = public as $$
  select * from public.coupons
  where code = upper(p_code) and active and (expires_at is null or expires_at > now())
    and (max_uses is null or used < max_uses)
$$;

-- p_items: [{ product_id, qty, note, options: ["optionId:valueId", ...] }]
create or replace function public.place_order(
  p_items jsonb, p_customer jsonb, p_notes text, p_coupon text, p_payment_method text
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_items jsonb := '[]';
  v_sub numeric := 0;
  v_disc numeric := 0;
  v_c public.coupons;
  v_line jsonb;
  v_p public.products;
  v_qty int;
  v_price numeric;
  v_id uuid;
  v_sel text[];
  v_o jsonb;
  v_v jsonb;
  v_n int;
  v_add numeric;
  v_chosen jsonb;
begin
  if auth.uid() is null then raise exception 'سجّل دخولك أولاً'; end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then raise exception 'السلة فاضية'; end if;
  if jsonb_array_length(p_items) > 50 then raise exception 'عدد الخدمات في الطلب كبير'; end if;
  -- no flooding: at most 15 orders an hour per account
  if (select count(*) from public.orders where user_id = auth.uid() and created_at > now() - interval '1 hour') >= 15 then
    raise exception 'محاولات كثيرة، حاول بعد شوي';
  end if;

  for v_line in select * from jsonb_array_elements(p_items) loop
    select * into v_p from public.products where id = v_line->>'product_id' and active;
    if not found then raise exception 'منتج غير متوفر: %', v_line->>'product_id'; end if;
    v_qty := greatest(1, least(999, coalesce((v_line->>'qty')::int, 1)));
    v_price := case when v_p.sale_price is not null and v_p.sale_price < v_p.price then v_p.sale_price else v_p.price end;

    -- options: only choices that exist on the product count; required ones must be chosen; "pick one" means one
    v_sel := array(select jsonb_array_elements_text(case when jsonb_typeof(v_line->'options') = 'array' then v_line->'options' else '[]'::jsonb end) limit 50);
    v_add := 0;
    v_chosen := '[]';
    for v_o in select * from jsonb_array_elements(coalesce(v_p.options, '[]'::jsonb)) loop
      v_n := 0;
      for v_v in select * from jsonb_array_elements(coalesce(v_o->'values', '[]'::jsonb)) loop
        if ((v_o->>'id') || ':' || (v_v->>'id')) = any(v_sel) then
          v_n := v_n + 1;
          v_add := v_add + greatest(0, coalesce((v_v->>'price')::numeric, 0));
          v_chosen := v_chosen || jsonb_build_object('option', v_o->>'name', 'value', v_v->>'name', 'price', greatest(0, coalesce((v_v->>'price')::numeric, 0)));
        end if;
      end loop;
      if coalesce((v_o->>'required')::boolean, false) and v_n = 0 then raise exception 'اختر «%» في %', v_o->>'name', v_p.name; end if;
      if v_o->>'type' = 'radio' and v_n > 1 then raise exception 'اختيار واحد بس في «%»', v_o->>'name'; end if;
    end loop;
    v_price := v_price + v_add;

    v_sub := v_sub + v_price * v_qty;
    v_items := v_items || jsonb_build_object(
      'productId', v_p.id, 'name', v_p.name, 'price', v_price, 'qty', v_qty,
      'image', v_p.image, 'digital', v_p.digital, 'note', left(coalesce(v_line->>'note', ''), 500), 'options', v_chosen);
  end loop;

  if p_coupon is not null and p_coupon <> '' then
    v_c := public.check_coupon(p_coupon);
    if v_c.code is null then raise exception 'الكود غير صالح أو منتهي'; end if;
    v_disc := least(v_sub, case when v_c.type = 'percent' then round(v_sub * least(v_c.value, 100) / 100, 2) else greatest(v_c.value, 0) end);
    -- count the use; a coupon with max_uses stops once it is used up
    update public.coupons set used = used + 1 where code = v_c.code and (max_uses is null or used < max_uses);
    if not found then raise exception 'كود الخصم انتهى عدد استخداماته'; end if;
  end if;

  insert into public.orders (user_id, customer, items, subtotal, discount, coupon, total, notes, payment_method, history, terms_accepted_at, terms_version)
  values (auth.uid(), p_customer, v_items, v_sub, v_disc, nullif(upper(p_coupon), ''), v_sub - v_disc,
          left(coalesce(p_notes, ''), 2000), 'card',  -- payment is online only (Tap); bank transfer was removed
          jsonb_build_array(jsonb_build_object('status', 'pending', 'at', now())),
          now(), '2026-10')  -- checkout can't submit without accepting the terms (src/data/terms.js TERMS_VERSION)
  returning id into v_id;
  return v_id;
end $$;

-- Guests can't call order/coupon functions (checkout needs an account anyway) — stops coupon guessing by bots
revoke execute on function public.check_coupon(text) from anon, public;
revoke execute on function public.place_order(jsonb, jsonb, text, text, text) from anon, public;
grant execute on function public.check_coupon(text) to authenticated;
grant execute on function public.place_order(jsonb, jsonb, text, text, text) to authenticated;

-- Customers may edit only their name and phone, at sane lengths
revoke update on public.profiles from authenticated;
grant update (name, phone) on public.profiles to authenticated;
do $$ begin
  alter table public.profiles add constraint profiles_sizes check (length(name) <= 120 and length(phone) <= 20) not valid;
exception when duplicate_object then null; end $$;

-- No negative prices or over-100% coupons, even by a typo in the dashboard
do $$ begin
  alter table public.products add constraint products_sale_price_ok check (sale_price is null or sale_price >= 0) not valid;
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.coupons add constraint coupons_value_ok check (value >= 0 and (type <> 'percent' or value <= 100)) not valid;
exception when duplicate_object then null; end $$;


-- ===================== hardening.sql =====================
-- Store — security hardening (run once in Supabase → SQL Editor). Safe to run again.

-- 1) Customers may change only their name and phone: role AND email are locked for non-admins.
create or replace function public.protect_role() returns trigger
language plpgsql as $$
begin
  -- auth.uid() is null for the SQL editor and service role, which may change anything
  if auth.uid() is not null and not public.is_admin() then
    new.role := old.role;
    new.email := old.email;
  end if;
  return new;
end $$;

-- 2) Order contact details are trimmed to sane sizes, and the email always comes from the signed-in account
--    (the browser can't put someone else's email on an order or flood it with huge text).
create or replace function public.orders_sanitize() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  new.customer := jsonb_build_object(
    'name',  left(coalesce(new.customer->>'name', ''), 120),
    'phone', left(coalesce(new.customer->>'phone', ''), 20),
    'email', coalesce((select u.email from auth.users u where u.id = new.user_id), left(coalesce(new.customer->>'email', ''), 160))
  );
  new.notes := left(new.notes, 2000);
  if jsonb_array_length(coalesce(new.items, '[]'::jsonb)) > 50 then
    raise exception 'too many items';
  end if;
  return new;
end $$;
drop trigger if exists orders_sanitize on public.orders;
create trigger orders_sanitize before insert on public.orders
  for each row execute function public.orders_sanitize();

-- 4) Remembers which order emails were already sent (so a retry or webhook never sends one twice).
alter table public.orders add column if not exists notified text[] not null default '{}';


-- ===================== designer.sql =====================
-- Store designer (لوحة التحكم ← مصمم المتجر): one row of look-and-feel settings. Safe to run more than once.
create table if not exists public.site_settings (
  id text primary key,
  data jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  constraint site_settings_size check (pg_column_size(data) < 32000)
);
alter table public.site_settings enable row level security;

drop policy if exists "settings public read" on public.site_settings;
create policy "settings public read" on public.site_settings for select using (true);
drop policy if exists "settings admin write" on public.site_settings;
create policy "settings admin write" on public.site_settings for all using (public.is_admin()) with check (public.is_admin());

grant select on public.site_settings to anon, authenticated;
grant insert, update on public.site_settings to authenticated;


-- ===================== security-2026-10.sql =====================
-- Store — security fixes (October 2026). Run once in Supabase → SQL Editor, AFTER the other files. Safe to run again.

-- 1) A cancelled unpaid order gives its coupon use back (admin cancel, or the customer starting a new checkout).
create or replace function public.orders_coupon_release() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if old.status = 'pending' and new.status = 'cancelled' and new.coupon is not null then
    update public.coupons set used = greatest(used - 1, 0) where code = new.coupon;
  end if;
  return new;
end $$;
drop trigger if exists orders_coupon_release on public.orders;
create trigger orders_coupon_release after update of status on public.orders
  for each row execute function public.orders_coupon_release();

-- 2) place_order: same as before, plus the "one open checkout per code" rule above.
create or replace function public.place_order(
  p_items jsonb, p_customer jsonb, p_notes text, p_coupon text, p_payment_method text
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_items jsonb := '[]';
  v_sub numeric := 0;
  v_disc numeric := 0;
  v_c public.coupons;
  v_line jsonb;
  v_p public.products;
  v_qty int;
  v_price numeric;
  v_id uuid;
  v_sel text[];
  v_o jsonb;
  v_v jsonb;
  v_n int;
  v_add numeric;
  v_chosen jsonb;
begin
  if auth.uid() is null then raise exception 'سجّل دخولك أولاً'; end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then raise exception 'السلة فاضية'; end if;
  if jsonb_array_length(p_items) > 50 then raise exception 'عدد الخدمات في الطلب كبير'; end if;
  -- no flooding: at most 15 orders an hour per account
  if (select count(*) from public.orders where user_id = auth.uid() and created_at > now() - interval '1 hour') >= 15 then
    raise exception 'محاولات كثيرة، حاول بعد شوي';
  end if;

  for v_line in select * from jsonb_array_elements(p_items) loop
    select * into v_p from public.products where id = v_line->>'product_id' and active;
    if not found then raise exception 'منتج غير متوفر: %', v_line->>'product_id'; end if;
    v_qty := greatest(1, least(999, coalesce((v_line->>'qty')::int, 1)));
    v_price := case when v_p.sale_price is not null and v_p.sale_price < v_p.price then v_p.sale_price else v_p.price end;

    -- options: only choices that exist on the product count; required ones must be chosen; "pick one" means one
    v_sel := array(select jsonb_array_elements_text(case when jsonb_typeof(v_line->'options') = 'array' then v_line->'options' else '[]'::jsonb end) limit 50);
    v_add := 0;
    v_chosen := '[]';
    for v_o in select * from jsonb_array_elements(coalesce(v_p.options, '[]'::jsonb)) loop
      v_n := 0;
      for v_v in select * from jsonb_array_elements(coalesce(v_o->'values', '[]'::jsonb)) loop
        if ((v_o->>'id') || ':' || (v_v->>'id')) = any(v_sel) then
          v_n := v_n + 1;
          v_add := v_add + greatest(0, coalesce((v_v->>'price')::numeric, 0));
          v_chosen := v_chosen || jsonb_build_object('option', v_o->>'name', 'value', v_v->>'name', 'price', greatest(0, coalesce((v_v->>'price')::numeric, 0)));
        end if;
      end loop;
      if coalesce((v_o->>'required')::boolean, false) and v_n = 0 then raise exception 'اختر «%» في %', v_o->>'name', v_p.name; end if;
      if v_o->>'type' = 'radio' and v_n > 1 then raise exception 'اختيار واحد بس في «%»', v_o->>'name'; end if;
    end loop;
    v_price := v_price + v_add;

    v_sub := v_sub + v_price * v_qty;
    v_items := v_items || jsonb_build_object(
      'productId', v_p.id, 'name', v_p.name, 'price', v_price, 'qty', v_qty,
      'image', v_p.image, 'digital', v_p.digital, 'note', left(coalesce(v_line->>'note', ''), 500), 'options', v_chosen);
  end loop;

  if p_coupon is not null and p_coupon <> '' then
    -- one open checkout per account per code: an earlier unpaid order with the same code is cancelled
    -- (the release trigger gives its use back), so unpaid orders can't eat up a limited coupon
    update public.orders
       set status = 'cancelled',
           history = history || jsonb_build_array(jsonb_build_object('status', 'cancelled', 'at', now(), 'note', 'استُبدل بطلب أحدث بنفس كود الخصم'))
     where user_id = auth.uid() and status = 'pending' and coupon = upper(p_coupon);
    v_c := public.check_coupon(p_coupon);
    if v_c.code is null then raise exception 'الكود غير صالح أو منتهي'; end if;
    v_disc := least(v_sub, case when v_c.type = 'percent' then round(v_sub * least(v_c.value, 100) / 100, 2) else greatest(v_c.value, 0) end);
    -- count the use; a coupon with max_uses stops once it is used up
    update public.coupons set used = used + 1 where code = v_c.code and (max_uses is null or used < max_uses);
    if not found then raise exception 'كود الخصم انتهى عدد استخداماته'; end if;
  end if;

  insert into public.orders (user_id, customer, items, subtotal, discount, coupon, total, notes, payment_method, history, terms_accepted_at, terms_version)
  values (auth.uid(), p_customer, v_items, v_sub, v_disc, nullif(upper(p_coupon), ''), v_sub - v_disc,
          left(coalesce(p_notes, ''), 2000), 'card',  -- payment is online only (Tap); bank transfer was removed
          jsonb_build_array(jsonb_build_object('status', 'pending', 'at', now())),
          now(), '2026-10')  -- checkout can't submit without accepting the terms (src/data/terms.js TERMS_VERSION)
  returning id into v_id;
  return v_id;
end $$;

-- 3) Order status: only the store's known statuses, and a paid order can't go back to "awaiting payment"
--    (that would let a second card payment be taken for it).
create or replace function public.set_order_status(p_order uuid, p_status text, p_note text) returns void
language plpgsql security definer set search_path = public as $$
declare v_old text;
begin
  if not public.is_admin() then raise exception 'هذه العملية للإدارة فقط'; end if;
  if p_status not in ('pending', 'paid', 'in_progress', 'review', 'completed', 'cancelled') then raise exception 'حالة غير معروفة'; end if;
  select status into v_old from public.orders where id = p_order for update;
  if v_old is null then raise exception 'الطلب غير موجود'; end if;
  if p_status = 'pending' and v_old <> 'pending' then raise exception 'ما يصير ترجع الطلب لـ«بانتظار الدفع» بعد ما تغيّرت حالته'; end if;
  update public.orders
     set status = p_status,
         history = history || jsonb_build_object('status', p_status, 'at', now(), 'note', left(coalesce(p_note, ''), 500))
   where id = p_order;
end $$;

-- 4) Re-apply the tighter grants (re-running schema.sql would have opened these again)
revoke execute on function public.check_coupon(text) from anon, public;
revoke execute on function public.place_order(jsonb, jsonb, text, text, text) from anon, public;
revoke execute on function public.set_order_status(uuid, text, text) from anon, public;
grant execute on function public.check_coupon(text) to authenticated;
grant execute on function public.place_order(jsonb, jsonb, text, text, text) to authenticated;
grant execute on function public.set_order_status(uuid, text, text) to authenticated;
revoke update on public.profiles from authenticated;
grant update (name, phone) on public.profiles to authenticated;

-- 5) The public images bucket takes images only, up to 5 MB (the private downloads bucket is unchanged).
update storage.buckets
   set allowed_mime_types = array['image/png', 'image/jpeg', 'image/webp', 'image/gif', 'image/avif', 'image/svg+xml'],
       file_size_limit = 5242880
 where id = 'products';


-- ===================== reports.sql =====================
-- Store — Reports (التقارير): first-party visitor tracking + one admin report function.
-- Run once in Supabase → SQL Editor (after the other files). Safe to run again.

-- 1) Every page view / cart / checkout from the store. Written only by the server (/api/hit, service role);
--    nobody reads it directly — the admin sees it through admin_report below.
create table if not exists public.visits (
  id uuid primary key,
  at timestamptz not null default now(),
  kind text not null default 'view' check (kind in ('view', 'cart', 'checkout')),
  vid text not null,              -- random id kept in the visitor's browser (no name, email or IP)
  sid text not null,              -- one visit; a new one after 30 minutes of no activity
  path text not null default '/',
  ref text,                       -- the referring site (host only)
  source text not null default 'مباشر',
  campaign text,
  country text,
  city text,
  device text,
  os text,
  browser text,
  dur int                         -- seconds the page was on screen
);
create index if not exists visits_at_idx on public.visits (at);
create index if not exists visits_vid_idx on public.visits (vid, at);
alter table public.visits enable row level security;
revoke all on public.visits from anon, authenticated;
grant all on public.visits to service_role;

-- 2) The whole report for a period, in one call (admins only).
create or replace function public.admin_report(p_from timestamptz, p_to timestamptz) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_len interval := p_to - p_from;
  v_out jsonb;
begin
  if not public.is_admin() then raise exception 'هذه العملية للإدارة فقط'; end if;
  if p_to <= p_from or v_len > interval '400 days' then raise exception 'فترة غير صالحة'; end if;

  with
  v    as (select * from public.visits where at >= p_from and at < p_to),
  pv   as (select * from v where kind = 'view'),
  prv  as (select * from public.visits where kind = 'view' and at >= p_from - v_len and at < p_from),
  sess as (select sid, count(*) as n, coalesce(sum(dur), 0) as d, min(at) as first_at from pv group by sid),
  firsts as (select distinct on (sid) sid, source from pv order by sid, at),
  o    as (select * from public.orders where created_at >= p_from and created_at < p_to),
  paid as (select * from o where status not in ('pending', 'cancelled')),
  ppaid as (select * from public.orders where created_at >= p_from - v_len and created_at < p_from and status not in ('pending', 'cancelled')),
  days as (select generate_series((p_from at time zone 'Asia/Riyadh')::date, ((p_to - interval '1 second') at time zone 'Asia/Riyadh')::date, interval '1 day')::date as d),
  dv   as (select (at at time zone 'Asia/Riyadh')::date as d, count(distinct vid) as visitors, count(*) as views from pv group by 1),
  ds   as (select (created_at at time zone 'Asia/Riyadh')::date as d, count(*) as orders, sum(total) as revenue from paid group by 1),
  items as (select i from paid, jsonb_array_elements(paid.items) as i)
  select jsonb_build_object(
    'visitors',    (select count(distinct vid) from pv),
    'views',       (select count(*) from pv),
    'sessions',    (select count(*) from sess),
    'bounce',      (select coalesce(round(100.0 * count(*) filter (where n = 1) / nullif(count(*), 0), 1), 0) from sess),
    'avgDuration', (select coalesce(round(avg(d)), 0) from sess),
    'newVisitors', (select count(distinct pv.vid) from pv where not exists (select 1 from public.visits x where x.vid = pv.vid and x.at < p_from)),
    'live',        (select count(distinct vid) from public.visits where at > now() - interval '5 minutes'),
    'liveList',    (select coalesce(jsonb_agg(l order by l.at desc), '[]') from (
                      select distinct on (vid) vid, path, country, city, device, source, at
                        from public.visits where kind = 'view' and at > now() - interval '5 minutes'
                       order by vid, at desc limit 30) l),
    'carts',       (select count(distinct vid) from v where kind = 'cart'),
    'checkouts',   (select count(distinct vid) from v where kind = 'checkout'),
    'revenue',     (select coalesce(sum(total), 0) from paid),
    'paidOrders',  (select count(*) from paid),
    'buyers',      (select count(distinct user_id) from paid),
    'discount',    (select coalesce(sum(discount), 0) from paid),
    'pending',     (select count(*) from o where status = 'pending'),
    'cancelled',   (select count(*) from o where status = 'cancelled'),
    'newCustomers',(select count(*) from public.profiles where role = 'customer' and created_at >= p_from and created_at < p_to),
    'prev', jsonb_build_object(
      'visitors', (select count(distinct vid) from prv),
      'views',    (select count(*) from prv),
      'revenue',  (select coalesce(sum(total), 0) from ppaid),
      'orders',   (select count(*) from ppaid)),
    'daily', (select coalesce(jsonb_agg(jsonb_build_object('day', days.d, 'visitors', coalesce(dv.visitors, 0), 'views', coalesce(dv.views, 0),
                                                           'orders', coalesce(ds.orders, 0), 'revenue', coalesce(ds.revenue, 0)) order by days.d), '[]')
                from days left join dv on dv.d = days.d left join ds on ds.d = days.d),
    'pages',     (select coalesce(jsonb_agg(x), '[]') from (select path as k, count(*) as n, count(distinct vid) as u from pv group by path order by n desc limit 12) x),
    'sources',   (select coalesce(jsonb_agg(x), '[]') from (select source as k, count(*) as n from firsts group by source order by n desc limit 10) x),
    'campaigns', (select coalesce(jsonb_agg(x), '[]') from (select campaign as k, count(distinct sid) as n from pv where campaign is not null group by campaign order by n desc limit 10) x),
    'countries', (select coalesce(jsonb_agg(x), '[]') from (select coalesce(country, '??') as k, count(distinct vid) as n from pv group by 1 order by n desc limit 10) x),
    'cities',    (select coalesce(jsonb_agg(x), '[]') from (select city as k, count(distinct vid) as n from pv where city is not null group by city order by n desc limit 10) x),
    'devices',   (select coalesce(jsonb_agg(x), '[]') from (select coalesce(device, 'غير معروف') as k, count(distinct vid) as n from pv group by 1 order by n desc) x),
    'browsers',  (select coalesce(jsonb_agg(x), '[]') from (select coalesce(browser, 'غير معروف') as k, count(distinct vid) as n from pv group by 1 order by n desc limit 8) x),
    'systems',   (select coalesce(jsonb_agg(x), '[]') from (select coalesce(os, 'غير معروف') as k, count(distinct vid) as n from pv group by 1 order by n desc limit 8) x),
    'hours',     (select coalesce(jsonb_agg(x order by x.k), '[]') from (select extract(hour from at at time zone 'Asia/Riyadh')::int as k, count(*) as n from pv group by 1) x),
    'products',  (select coalesce(jsonb_agg(x), '[]') from (
                    select i->>'productId' as id, max(i->>'name') as k, sum((i->>'qty')::int) as qty, sum((i->>'price')::numeric * (i->>'qty')::int) as n
                      from items group by i->>'productId' order by n desc limit 10) x),
    'coupons',   (select coalesce(jsonb_agg(x), '[]') from (select coupon as k, count(*) as n, sum(discount) as d from paid where coupon is not null group by coupon order by n desc limit 10) x)
  ) into v_out;
  return v_out;
end $$;

revoke execute on function public.admin_report(timestamptz, timestamptz) from anon, public;
grant execute on function public.admin_report(timestamptz, timestamptz) to authenticated;


-- ===================== login-code-2026-10.sql =====================
-- Store — every sign-in is an email code (October 2026).
-- Run once in Supabase → SQL Editor, AFTER the other files. Safe to run again.

-- 1) No passwords: every existing account loses its password, so no password can open any account any more,
--    not even straight through the Supabase API. Customers and the owner sign in with the code emailed to them
--    (the store's login pages only ever ask for that code).
update auth.users set encrypted_password = '' where coalesce(encrypted_password, '') <> '';

-- 2) Owner powers come only from a session that signed in with a code. A session that signed in with a password
--    (one still open from before this change, or a password set again later through the API) is treated as a
--    customer session: it sees the customer's own data, never the dashboard's.
create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin')
     and not exists (
       select 1 from jsonb_array_elements(coalesce(auth.jwt() -> 'amr', '[]'::jsonb)) m
       where m ->> 'method' = 'password'
     )
$$;


-- ===================== login-2fa-2026-10.sql =====================
-- Store — two-step sign-in: password, then a code by email (October 2026).
-- Run once in Supabase → SQL Editor, AFTER login-code-2026-10.sql. Safe to run again.
-- How it works: the store's server checks the password (api/login-start.js), records it here, and only then emails a
-- code. The dashboard accepts a session only when it signed in with that code right after a recorded password,
-- so neither the password alone nor a code requested straight from Supabase opens it.

-- 1) Correct passwords, recorded by the server (no one else can read or write them)
create table if not exists public.login_checks (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  at timestamptz not null default now()
);
create index if not exists login_checks_user_at on public.login_checks(user_id, at desc);
alter table public.login_checks enable row level security; -- no policies: only the server (service role) uses it
revoke all on public.login_checks from anon, authenticated;

-- 2) Owner powers: a code session that follows a recorded password within 15 minutes, never a password session
create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  with s as (
    select coalesce(auth.jwt() -> 'amr', '[]'::jsonb) as amr
  ), t as (
    select to_timestamp(max((m ->> 'timestamp')::bigint)) as signed_in,
           bool_or(m ->> 'method' = 'password') as by_password
    from s, jsonb_array_elements(s.amr) m
  )
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin')
     and coalesce((select not by_password from t), false)
     and exists (
       select 1 from public.login_checks c, t
       where c.user_id = auth.uid()
         and c.at between t.signed_in - interval '15 minutes' and t.signed_in + interval '1 minute'
     )
$$;

-- 3) Old checks are not needed after a day
create or replace function public.login_checks_prune() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  delete from public.login_checks where at < now() - interval '1 day';
  return null;
end $$;
drop trigger if exists login_checks_prune on public.login_checks;
create trigger login_checks_prune after insert on public.login_checks for each statement execute function public.login_checks_prune();


-- ===================== staff-2026-10.sql =====================
-- Store — staff and permissions (October 2026).
-- Run once in Supabase → SQL Editor, AFTER login-2fa-2026-10.sql. Safe to run again.
-- The owner (profiles.role = 'admin') keeps everything. Staff are added by email from لوحة التحكم ← الفريق والصلاحيات
-- (api/staff.js), each with the dashboard areas they may open. Staff sign in exactly like the owner: password, then
-- the emailed code; no area opens for a password-only session.

-- 1) The team (only the server reads or writes it; the dashboard goes through api/staff.js)
create table if not exists public.staff (
  email text primary key check (email = lower(email) and email like '%_@_%'),
  name text not null default '',
  role text not null default '',
  perms text[] not null default '{}' check (perms <@ array['orders', 'reports', 'products', 'categories', 'customers', 'coupons', 'design']::text[]),
  added_at timestamptz not null default now()
);
alter table public.staff enable row level security; -- no policies
revoke all on public.staff from anon, authenticated;
grant all on public.staff to service_role;

-- 2) A two-step session: signed in by the emailed code, right after a correct password (see login-2fa-2026-10.sql)
create or replace function public.strong_session() returns boolean
language sql stable security definer set search_path = public as $$
  with s as (
    select coalesce(auth.jwt() -> 'amr', '[]'::jsonb) as amr
  ), t as (
    select to_timestamp(max((m ->> 'timestamp')::bigint)) as signed_in,
           bool_or(m ->> 'method' = 'password') as by_password
    from s, jsonb_array_elements(s.amr) m
  )
  select auth.uid() is not null
     and coalesce((select not by_password from t), false)
     and exists (
       select 1 from public.login_checks c, t
       where c.user_id = auth.uid()
         and c.at between t.signed_in - interval '15 minutes' and t.signed_in + interval '1 minute'
     )
$$;

-- 3) The owner (unchanged meaning: role admin + two-step session) — used where only the owner may act
create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin') and public.strong_session()
$$;

-- 4) May this session use one dashboard area? The owner may use all of them.
create or replace function public.has_perm(p text) returns boolean
language sql stable security definer set search_path = public as $$
  select public.strong_session() and (
    exists (select 1 from public.profiles where id = auth.uid() and role = 'admin')
    or exists (select 1 from public.staff s join auth.users u on lower(u.email) = s.email where u.id = auth.uid() and p = any(s.perms))
  )
$$;

-- 5) What the signed-in person may open (the dashboard draws its menu from this)
create or replace function public.my_access() returns jsonb
language sql stable security definer set search_path = public as $$
  select case
    when not public.strong_session() then jsonb_build_object('owner', false, 'role', '', 'perms', '[]'::jsonb, 'strong', false)
    when exists (select 1 from public.profiles where id = auth.uid() and role = 'admin')
      then jsonb_build_object('owner', true, 'role', 'المالك', 'perms', to_jsonb(array['orders', 'reports', 'products', 'categories', 'customers', 'coupons', 'design', 'team']), 'strong', true)
    else coalesce((select jsonb_build_object('owner', false, 'role', s.role, 'perms', to_jsonb(s.perms), 'strong', true)
                     from public.staff s join auth.users u on lower(u.email) = s.email where u.id = auth.uid()),
                  jsonb_build_object('owner', false, 'role', '', 'perms', '[]'::jsonb, 'strong', true))
  end
$$;

revoke execute on function public.strong_session() from public;
revoke execute on function public.my_access() from public, anon;
grant execute on function public.strong_session(), public.has_perm(text), public.is_admin() to anon, authenticated;
grant execute on function public.my_access() to authenticated;

-- 6) Each table follows its own area
drop policy if exists "categories admin" on public.categories;
create policy "categories admin" on public.categories for all using ((select public.has_perm('categories'))) with check ((select public.has_perm('categories')));

drop policy if exists "products public" on public.products;
create policy "products public" on public.products for select using (active or (select public.has_perm('products')));
drop policy if exists "products admin" on public.products;
create policy "products admin" on public.products for all using ((select public.has_perm('products'))) with check ((select public.has_perm('products')));

drop policy if exists "files admin" on public.product_files;
create policy "files admin" on public.product_files for all using ((select public.has_perm('products'))) with check ((select public.has_perm('products')));

drop policy if exists "orders own read" on public.orders;
create policy "orders own read" on public.orders for select using (user_id = auth.uid() or (select public.has_perm('orders')));

drop policy if exists "coupons admin" on public.coupons;
create policy "coupons admin" on public.coupons for all using ((select public.has_perm('coupons'))) with check ((select public.has_perm('coupons')));

drop policy if exists "settings admin write" on public.site_settings;
create policy "settings admin write" on public.site_settings for all using ((select public.has_perm('design'))) with check ((select public.has_perm('design')));

-- images: products and the store designer upload to «products»; the private «downloads» files are products only
drop policy if exists "product images admin write" on storage.objects;
create policy "product images admin write" on storage.objects for insert with check (
  (bucket_id = 'products' and (public.has_perm('products') or public.has_perm('design'))) or (bucket_id = 'downloads' and public.has_perm('products')));
drop policy if exists "product images admin update" on storage.objects;
create policy "product images admin update" on storage.objects for update using (
  (bucket_id = 'products' and (public.has_perm('products') or public.has_perm('design'))) or (bucket_id = 'downloads' and public.has_perm('products')));
drop policy if exists "product images admin delete" on storage.objects;
create policy "product images admin delete" on storage.objects for delete using (
  (bucket_id = 'products' and (public.has_perm('products') or public.has_perm('design'))) or (bucket_id = 'downloads' and public.has_perm('products')));

-- 7) The dashboard functions check their own area (same bodies, only the check changes; grants are kept)
do $$
declare f record; d text;
begin
  for f in select * from (values
    ('public.set_order_status(uuid,text,text)', 'orders'),
    ('public.admin_customers()', 'customers'),
    ('public.set_product_file(text,text)', 'products'),
    ('public.admin_report(timestamptz,timestamptz)', 'reports')
  ) v(fn, perm) loop
    if to_regprocedure(f.fn) is null then continue; end if;
    d := pg_get_functiondef(f.fn::regprocedure);
    d := replace(d, 'not public.is_admin()', format('not public.has_perm(%L)', f.perm));
    execute d;
  end loop;
end $$;

-- 8) Staff are not customers: keep them out of the customers list
do $$
declare d text;
begin
  d := pg_get_functiondef('public.admin_customers()'::regprocedure);
  if position('public.staff' in d) = 0 then
    d := replace(d, 'where p.role = ''customer''', 'where p.role = ''customer'' and lower(p.email) not in (select email from public.staff)');
    execute d;
  end if;
end $$;


