-- Store — fix: the server may record correct passwords (October 2026). Run once in Supabase → SQL Editor.
-- login_checks was created without a grant for the server (service_role), so every check silently failed to save
-- and the dashboard never recognised a two-step sign-in. Safe to run again.
grant all on public.login_checks to service_role;
grant all on public.staff to service_role;
grant usage, select on all sequences in schema public to service_role;

-- should show «نعم» twice
select 'login_checks' as "الجدول", case when has_table_privilege('service_role', 'public.login_checks', 'insert') then 'نعم' else 'لا' end as "الخادم يقدر يكتب"
union all
select 'staff', case when has_table_privilege('service_role', 'public.staff', 'insert') then 'نعم' else 'لا' end;


-- ===================== owner-tools-2026-10.sql =====================
-- Store — owner tools (October 2026): design backups, manual orders, deleting orders.
-- Run once in Supabase → SQL Editor, AFTER staff-2026-10.sql. Safe to run again.

-- =====================================================================================================
-- 1) Design backups: every save of the store design (site_settings) is kept as a dated copy.
--    Only the owner can list them or bring one back (from مصمم المتجر ← النسخ الاحتياطية).
-- =====================================================================================================
create table if not exists public.settings_versions (
  id bigserial primary key,
  data jsonb not null,
  at timestamptz not null default now(),
  by_email text not null default '',
  note text not null default ''
);
create index if not exists settings_versions_at_idx on public.settings_versions (at desc);
alter table public.settings_versions enable row level security; -- no policies: only the functions below read it
revoke all on public.settings_versions from anon, authenticated;
grant all on public.settings_versions to service_role;

create or replace function public.settings_keep_version() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'UPDATE' and new.data is not distinct from old.data then return new; end if;
  insert into public.settings_versions (data, by_email, note)
  values (new.data,
          coalesce((select u.email from auth.users u where u.id = auth.uid()), ''),
          coalesce(nullif(current_setting('raed.version_note', true), ''), ''));
  -- keep the latest 200
  delete from public.settings_versions where id in (select id from public.settings_versions order by at desc, id desc offset 200);
  return new;
end $$;
drop trigger if exists site_settings_keep_version on public.site_settings;
create trigger site_settings_keep_version after insert or update on public.site_settings
  for each row execute function public.settings_keep_version();

-- the design as it is now becomes the first backup
insert into public.settings_versions (data, at, note)
select s.data, s.updated_at, 'التصميم قبل تفعيل النسخ الاحتياطية'
  from public.site_settings s
 where s.id = 'main' and not exists (select 1 from public.settings_versions);

-- the list (owner only)
create or replace function public.owner_design_versions() returns table (id bigint, at timestamptz, by_email text, note text, current boolean)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'النسخ الاحتياطية للمالك فقط'; end if;
  return query
    select v.id, v.at, v.by_email, v.note,
           v.id = (select max(x.id) from public.settings_versions x where x.data = (select s.data from public.site_settings s where s.id = 'main'))
      from public.settings_versions v
     order by v.at desc, v.id desc;
end $$;

-- bring one back (owner only); the restore itself is kept as a new version too
create or replace function public.owner_restore_design(p_id bigint) returns void
language plpgsql security definer set search_path = public as $$
declare v public.settings_versions;
begin
  if not public.is_admin() then raise exception 'النسخ الاحتياطية للمالك فقط'; end if;
  select * into v from public.settings_versions where id = p_id;
  if v.id is null then raise exception 'النسخة غير موجودة'; end if;
  perform set_config('raed.version_note', 'استرجاع نسخة ' || to_char(v.at at time zone 'Asia/Riyadh', 'YYYY-MM-DD HH24:MI'), true);
  insert into public.site_settings (id, data, updated_at) values ('main', v.data, now())
  on conflict (id) do update set data = excluded.data, updated_at = now();
end $$;

revoke execute on function public.owner_design_versions() from public, anon;
revoke execute on function public.owner_restore_design(bigint) from public, anon;
grant execute on function public.owner_design_versions() to authenticated;
grant execute on function public.owner_restore_design(bigint) to authenticated;

-- =====================================================================================================
-- 2) A new order from the dashboard (whoever has the «orders» area).
--    p_items: [{ product_id, qty, options: ["optionId:valueId"] }] or a free line [{ name, price, qty }]
--    Prices of store services come from the database, like checkout. p_status: 'pending' or 'paid'.
-- =====================================================================================================
create or replace function public.admin_create_order(
  p_user uuid, p_items jsonb, p_status text, p_notes text, p_discount numeric
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_items jsonb := '[]'; v_sub numeric := 0; v_disc numeric; v_line jsonb; v_p public.products;
  v_qty int; v_price numeric; v_id uuid; v_sel text[]; v_o jsonb; v_v jsonb; v_add numeric; v_chosen jsonb;
  v_prof public.profiles;
begin
  if not public.has_perm('orders') then raise exception 'ما عندك صلاحية الطلبات'; end if;
  if p_status not in ('pending', 'paid') then raise exception 'حالة غير صالحة'; end if;
  select * into v_prof from public.profiles where id = p_user;
  if v_prof.id is null then raise exception 'العميل غير موجود'; end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then raise exception 'أضف خدمة واحدة على الأقل'; end if;
  if jsonb_array_length(p_items) > 50 then raise exception 'عدد الخدمات كبير'; end if;

  for v_line in select * from jsonb_array_elements(p_items) loop
    v_qty := greatest(1, least(999, coalesce((v_line->>'qty')::int, 1)));
    if coalesce(v_line->>'product_id', '') <> '' then
      select * into v_p from public.products where id = v_line->>'product_id';
      if v_p.id is null then raise exception 'خدمة غير موجودة: %', v_line->>'product_id'; end if;
      v_price := case when v_p.sale_price is not null and v_p.sale_price < v_p.price then v_p.sale_price else v_p.price end;
      v_sel := array(select jsonb_array_elements_text(case when jsonb_typeof(v_line->'options') = 'array' then v_line->'options' else '[]'::jsonb end) limit 50);
      v_add := 0; v_chosen := '[]';
      for v_o in select * from jsonb_array_elements(coalesce(v_p.options, '[]'::jsonb)) loop
        for v_v in select * from jsonb_array_elements(coalesce(v_o->'values', '[]'::jsonb)) loop
          if ((v_o->>'id') || ':' || (v_v->>'id')) = any(v_sel) then
            v_add := v_add + greatest(0, coalesce((v_v->>'price')::numeric, 0));
            v_chosen := v_chosen || jsonb_build_object('option', v_o->>'name', 'value', v_v->>'name', 'price', greatest(0, coalesce((v_v->>'price')::numeric, 0)));
          end if;
        end loop;
      end loop;
      v_price := v_price + v_add;
      v_items := v_items || jsonb_build_object('productId', v_p.id, 'name', v_p.name, 'price', v_price, 'qty', v_qty,
        'image', v_p.image, 'digital', v_p.digital, 'note', left(coalesce(v_line->>'note', ''), 500), 'options', v_chosen);
    else
      -- a free line written by the admin (custom work)
      if coalesce(trim(v_line->>'name'), '') = '' then raise exception 'اكتب اسم البند'; end if;
      v_price := round(coalesce((v_line->>'price')::numeric, -1), 2);
      if v_price < 0 or v_price > 1000000 then raise exception 'سعر البند غير صالح'; end if;
      v_items := v_items || jsonb_build_object('productId', null, 'name', left(trim(v_line->>'name'), 120), 'price', v_price, 'qty', v_qty,
        'image', null, 'digital', false, 'note', left(coalesce(v_line->>'note', ''), 500), 'options', '[]'::jsonb);
    end if;
    v_sub := v_sub + v_price * v_qty;
  end loop;

  v_disc := least(v_sub, greatest(0, round(coalesce(p_discount, 0), 2)));

  insert into public.orders (user_id, customer, items, subtotal, discount, total, notes, payment_method, payment_ref, status, history, terms_version)
  values (p_user,
          jsonb_build_object('name', v_prof.name, 'phone', v_prof.phone, 'email', v_prof.email),
          v_items, v_sub, v_disc, v_sub - v_disc, left(coalesce(p_notes, ''), 2000), 'card',
          case when p_status = 'paid' then 'manual' else null end,
          p_status,
          case when p_status = 'paid'
               then jsonb_build_array(jsonb_build_object('status', 'paid', 'at', now(), 'note', 'طلب يدوي من لوحة التحكم'))
               else jsonb_build_array(jsonb_build_object('status', 'pending', 'at', now(), 'note', 'طلب يدوي من لوحة التحكم')) end,
          'manual')
  returning id into v_id;
  return v_id;
end $$;

-- =====================================================================================================
-- 3) Delete an order (owner only)
-- =====================================================================================================
create or replace function public.owner_delete_order(p_order uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'حذف الطلبات للمالك فقط'; end if;
  delete from public.orders where id = p_order;
  if not found then raise exception 'الطلب غير موجود'; end if;
end $$;

revoke execute on function public.admin_create_order(uuid, jsonb, text, text, numeric) from public, anon;
revoke execute on function public.owner_delete_order(uuid) from public, anon;
grant execute on function public.admin_create_order(uuid, jsonb, text, text, numeric) to authenticated;
grant execute on function public.owner_delete_order(uuid) to authenticated;


-- ===================== customers-fix-2026-10.sql =====================
-- Store — fixes the customers list (October 2026): "column reference email is ambiguous".
-- Same list as before (customers only, no owner or team accounts), with every column named by its table.
create or replace function public.admin_customers() returns table (
  id uuid, name text, email text, phone text, "createdAt" timestamptz, orders bigint, spent numeric
)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.has_perm('customers') then raise exception 'هذه العملية للإدارة فقط'; end if;
  return query
    select p.id, p.name, p.email, p.phone, p.created_at,
           count(o.id),
           coalesce(sum(o.total) filter (where o.status not in ('pending', 'cancelled')), 0)
      from public.profiles p
      left join public.orders o on o.user_id = p.id
     where p.role = 'customer'
       and not exists (select 1 from public.staff s where s.email = lower(p.email))
     group by p.id
     order by p.created_at desc;
end $$;
revoke execute on function public.admin_customers() from public, anon;
grant execute on function public.admin_customers() to authenticated;

-- any account that signed up without a profile row gets one
insert into public.profiles (id, name, email, phone)
select u.id, coalesce(u.raw_user_meta_data->>'name', ''), coalesce(u.email, ''), coalesce(u.raw_user_meta_data->>'phone', '')
  from auth.users u
 where not exists (select 1 from public.profiles p where p.id = u.id)
on conflict (id) do nothing;


-- ===================== customers-all-2026-10.sql =====================
-- Store — the customers page lists every account (October 2026): customers, the owner and the team,
-- each with its kind ('owner' / 'staff' / 'customer') and the team role name.
drop function if exists public.admin_customers();
create function public.admin_customers() returns table (
  id uuid, name text, email text, phone text, "createdAt" timestamptz, orders bigint, spent numeric, kind text, "staffRole" text
)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.has_perm('customers') then raise exception 'هذه العملية للإدارة فقط'; end if;
  return query
    select p.id, p.name, p.email, p.phone, p.created_at,
           count(o.id),
           coalesce(sum(o.total) filter (where o.status not in ('pending', 'cancelled')), 0),
           case when p.role = 'admin' then 'owner' when s.email is not null then 'staff' else 'customer' end,
           coalesce(s.role, '')
      from public.profiles p
      left join public.staff s on s.email = lower(p.email)
      left join public.orders o on o.user_id = p.id
     group by p.id, s.email, s.role
     order by p.created_at desc;
end $$;
revoke execute on function public.admin_customers() from public, anon;
grant execute on function public.admin_customers() to authenticated;


-- ===================== customers-check-2026-10.sql =====================
-- Store — customers list check (October 2026). Safe to run any time.
-- 1) Any account that signed up without a profile row gets one (the customers list reads profiles).
insert into public.profiles (id, name, email, phone)
select u.id, coalesce(u.raw_user_meta_data->>'name', ''), coalesce(u.email, ''), coalesce(u.raw_user_meta_data->>'phone', '')
  from auth.users u
 where not exists (select 1 from public.profiles p where p.id = u.id)
on conflict (id) do nothing;

-- 2) Every account and why it is (or isn't) in the customers list
select u.email,
       u.created_at::date as created,
       coalesce(p.role, 'no profile') as role,
       (s.email is not null) as in_team,
       case when p.role = 'admin' then 'مالك: ما يظهر في العملاء'
            when s.email is not null then 'من الفريق: ما يظهر في العملاء'
            when p.role = 'customer' then 'عميل: يظهر'
            else 'بدون ملف' end as status
  from auth.users u
  left join public.profiles p on p.id = u.id
  left join public.staff s on s.email = lower(u.email)
 order by u.created_at desc;


-- ===================== reviews-2026-10.sql =====================
-- Store — customer reviews and service questions (October 2026).
-- Run once in Supabase → SQL Editor, AFTER blog-2026-10.sql. Safe to run again.
--  · When an order is marked «مكتمل», its email carries a private review link (/review/<order>?t=<token>).
--    The customer rates the service and the store (1–5) and writes a few words. 4 or 5 on both is published
--    at once; anything lower waits in لوحة التحكم ← التقييمات والأسئلة until the owner publishes or deletes it.
--  · Anyone can ask a question on a service page; it waits there until it is answered and published.
--  · Published ones show under the service, on the home page and on /reviews (after the automatic rebuild).

-- 1) A private token per order for its review link
alter table public.orders add column if not exists review_token uuid not null default gen_random_uuid();

-- 2) Reviews: one per order
create table if not exists public.reviews (
  id uuid primary key default gen_random_uuid(),
  order_id uuid unique references public.orders(id) on delete set null,
  products text[] not null default '{}' check (cardinality(products) <= 30),
  name text not null check (length(name) between 1 and 60),
  service_rating int not null check (service_rating between 1 and 5),
  store_rating int not null check (store_rating between 1 and 5),
  body text not null default '' check (length(body) <= 1000),
  status text not null default 'pending' check (status in ('pending', 'published', 'hidden')),
  created_at timestamptz not null default now(),
  published_at timestamptz
);
create index if not exists reviews_status_idx on public.reviews(status, created_at desc);

-- 3) Questions on a service
create table if not exists public.questions (
  id uuid primary key default gen_random_uuid(),
  product_id text references public.products(id) on delete cascade,
  name text not null check (length(name) between 1 and 60),
  contact text not null default '' check (length(contact) <= 120),
  question text not null check (length(question) between 3 and 600),
  answer text not null default '' check (length(answer) <= 2000),
  status text not null default 'pending' check (status in ('pending', 'published', 'hidden')),
  created_at timestamptz not null default now(),
  answered_at timestamptz
);
create index if not exists questions_status_idx on public.questions(status, created_at desc);

-- 4) «التقييمات والأسئلة» becomes one of the areas a staff member can be given
do $$
declare c text;
begin
  if to_regclass('public.staff') is null then return; end if;
  for c in select conname from pg_constraint where conrelid = 'public.staff'::regclass and contype = 'c' and pg_get_constraintdef(oid) like '%perms%' loop
    execute format('alter table public.staff drop constraint %I', c);
  end loop;
  alter table public.staff add constraint staff_perms_check
    check (perms <@ array['orders', 'reports', 'products', 'categories', 'customers', 'coupons', 'design', 'blog', 'reviews']::text[]);
end $$;

create or replace function public.my_access() returns jsonb
language sql stable security definer set search_path = public as $$
  select case
    when not public.strong_session() then jsonb_build_object('owner', false, 'role', '', 'perms', '[]'::jsonb, 'strong', false)
    when exists (select 1 from public.profiles where id = auth.uid() and role = 'admin')
      then jsonb_build_object('owner', true, 'role', 'المالك', 'perms', to_jsonb(array['orders', 'reports', 'products', 'categories', 'customers', 'coupons', 'design', 'blog', 'reviews', 'team']), 'strong', true)
    else coalesce((select jsonb_build_object('owner', false, 'role', s.role, 'perms', to_jsonb(s.perms), 'strong', true)
                     from public.staff s join auth.users u on lower(u.email) = s.email where u.id = auth.uid()),
                  jsonb_build_object('owner', false, 'role', '', 'perms', '[]'::jsonb, 'strong', true))
  end
$$;
revoke execute on function public.my_access() from public, anon;
grant execute on function public.my_access() to authenticated;

-- 5) The dashboard reads and manages both tables; the public never reads them directly
alter table public.reviews enable row level security;
alter table public.questions enable row level security;
drop policy if exists "reviews admin" on public.reviews;
create policy "reviews admin" on public.reviews for all using ((select public.has_perm('reviews'))) with check ((select public.has_perm('reviews')));
drop policy if exists "questions admin" on public.questions;
create policy "questions admin" on public.questions for all using ((select public.has_perm('reviews'))) with check ((select public.has_perm('reviews')));
revoke all on public.reviews, public.questions from anon;
grant select, update, delete on public.reviews, public.questions to authenticated;
grant all on public.reviews, public.questions to service_role;

-- 6) What the site shows: published reviews and answered questions, without order ids or contact details
create or replace function public.public_feedback() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'reviews', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name, 'products', to_jsonb(r.products),
        'service', r.service_rating, 'store', r.store_rating, 'text', r.body, 'date', to_char(coalesce(r.published_at, r.created_at), 'YYYY-MM-DD'))
        order by coalesce(r.published_at, r.created_at) desc)
      from public.reviews r where r.status = 'published'), '[]'::jsonb),
    'questions', coalesce((select jsonb_agg(jsonb_build_object('id', q.id, 'productId', q.product_id, 'name', q.name,
        'question', q.question, 'answer', q.answer, 'date', to_char(coalesce(q.answered_at, q.created_at), 'YYYY-MM-DD'))
        order by coalesce(q.answered_at, q.created_at) desc)
      from public.questions q where q.status = 'published' and q.answer <> ''), '[]'::jsonb))
$$;

-- 7) The review page: what the link opens (only a completed order, only with its own token)
create or replace function public.review_form(p_order uuid, p_token uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare o public.orders;
begin
  select * into o from public.orders where id = p_order and review_token = p_token;
  if o.id is null then return jsonb_build_object('ok', false, 'reason', 'not-found'); end if;
  if o.status <> 'completed' then return jsonb_build_object('ok', false, 'reason', 'not-completed'); end if;
  return jsonb_build_object('ok', true, 'number', o.number,
    'name', split_part(coalesce(o.customer->>'name', ''), ' ', 1),
    'items', coalesce((select jsonb_agg(jsonb_build_object('productId', it->>'productId', 'name', it->>'name'))
                        from jsonb_array_elements(o.items) it), '[]'::jsonb),
    'done', exists (select 1 from public.reviews where order_id = o.id));
end $$;

create or replace function public.submit_review(p_order uuid, p_token uuid, p_name text, p_service int, p_store int, p_body text) returns text
language plpgsql volatile security definer set search_path = public as $$
declare o public.orders; v_status text; v_name text := left(trim(coalesce(p_name, '')), 60);
begin
  select * into o from public.orders where id = p_order and review_token = p_token;
  if o.id is null then raise exception 'رابط التقييم غير صالح'; end if;
  if o.status <> 'completed' then raise exception 'التقييم يفتح بعد اكتمال الطلب'; end if;
  if exists (select 1 from public.reviews where order_id = o.id) then raise exception 'قيّمت هذا الطلب من قبل، شكراً لك'; end if;
  if p_service not between 1 and 5 or p_store not between 1 and 5 then raise exception 'اختر التقييم من 1 إلى 5'; end if;
  if v_name = '' then v_name := left(coalesce(nullif(split_part(o.customer->>'name', ' ', 1), ''), 'عميل'), 60); end if;
  v_status := case when p_service >= 4 and p_store >= 4 then 'published' else 'pending' end;
  insert into public.reviews (order_id, products, name, service_rating, store_rating, body, status, published_at)
  values (o.id,
          coalesce((select array_agg(distinct it->>'productId') from jsonb_array_elements(o.items) it where coalesce(it->>'productId', '') <> ''), '{}'),
          v_name, p_service, p_store, left(trim(coalesce(p_body, '')), 1000), v_status,
          case when v_status = 'published' then now() end);
  return v_status;
end $$;

-- 8) A question from a service page (waits for an answer); a light cap keeps the inbox from flooding
create or replace function public.ask_question(p_product text, p_name text, p_contact text, p_question text) returns boolean
language plpgsql volatile security definer set search_path = public as $$
declare v_q text := trim(coalesce(p_question, '')); v_name text := left(trim(coalesce(p_name, '')), 60);
begin
  if not exists (select 1 from public.products where id = p_product and active) then raise exception 'الخدمة غير موجودة'; end if;
  if length(v_q) < 3 then raise exception 'اكتب سؤالك'; end if;
  if v_name = '' then raise exception 'اكتب اسمك'; end if;
  if (select count(*) from public.questions where created_at > now() - interval '1 hour') >= 60 then raise exception 'حاول بعد شوي'; end if;
  insert into public.questions (product_id, name, contact, question) values (p_product, v_name, left(trim(coalesce(p_contact, '')), 120), left(v_q, 600));
  return true;
end $$;

revoke execute on function public.public_feedback(), public.review_form(uuid, uuid), public.submit_review(uuid, uuid, text, int, int, text), public.ask_question(text, text, text, text) from public;
grant execute on function public.public_feedback(), public.review_form(uuid, uuid), public.submit_review(uuid, uuid, text, int, int, text), public.ask_question(text, text, text, text) to anon, authenticated;

-- should show the two tables and the new staff rule
select (select count(*) from public.reviews) as "التقييمات", (select count(*) from public.questions) as "الأسئلة",
       exists (select 1 from pg_constraint where conname = 'staff_perms_check' and pg_get_constraintdef(oid) like '%reviews%') as "صلاحية التقييمات";


-- ===================== store-2026-10.sql =====================
-- Store — shipping (October 2026): every order carries a shipping address and a shipping fee.
-- Run AFTER security-2026-10.sql (install.sql already has it in order). Safe to run again.
--  · The address: Saudi national short address (4 letters + 4 digits, e.g. RRRD2929), city, district, street, details.
--  · The fee comes from the store designer (site_settings.data.shipping: fee, freeOver), never from the browser.
--    No setting saved yet = 35 SAR, the store's fee (Oct 2026).

alter table public.orders add column if not exists shipping jsonb;
alter table public.orders add column if not exists shipping_fee numeric(10, 2) not null default 0;

-- The fee for a subtotal, with the same rules as src/lib/theme.js (shippingFor + mergeSettings).
create or replace function public.shipping_fee_for(p_subtotal numeric) returns numeric
language sql stable security definer set search_path = public as $$
  -- no saved setting (or a missing value) falls back to the defaults: fee 35, never free
  with s as (
    select least(greatest(coalesce(round((select (data->'shipping'->>'fee')::numeric from public.site_settings where id = 'main'), 2), 35), 0), 500) as fee,
           least(greatest(coalesce(round((select (data->'shipping'->>'freeOver')::numeric from public.site_settings where id = 'main')), 0), 0), 100000) as free_over
  )
  select case when free_over > 0 and p_subtotal >= free_over then 0 else fee end from s
$$;

-- place_order now takes the shipping address (new signature, so the old one is dropped first).
drop function if exists public.place_order(jsonb, jsonb, text, text, text);
create or replace function public.place_order(
  p_items jsonb, p_customer jsonb, p_shipping jsonb, p_notes text, p_coupon text, p_payment_method text
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_items jsonb := '[]';
  v_sub numeric := 0;
  v_disc numeric := 0;
  v_fee numeric := 0;
  v_c public.coupons;
  v_line jsonb;
  v_p public.products;
  v_qty int;
  v_price numeric;
  v_id uuid;
  v_sel text[];
  v_o jsonb;
  v_v jsonb;
  v_n int;
  v_add numeric;
  v_chosen jsonb;
  v_short text;
  v_ship jsonb;
begin
  if auth.uid() is null then raise exception 'سجّلي دخولك أولاً'; end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then raise exception 'السلة فاضية'; end if;
  if jsonb_array_length(p_items) > 50 then raise exception 'عدد المنتجات في الطلب كبير'; end if;
  -- no flooding: at most 15 orders an hour per account
  if (select count(*) from public.orders where user_id = auth.uid() and created_at > now() - interval '1 hour') >= 15 then
    raise exception 'محاولات كثيرة، حاولي بعد شوي';
  end if;

  -- the shipping address: the short national address is required and checked, the rest is trimmed and capped
  if p_shipping is null or jsonb_typeof(p_shipping) <> 'object' then raise exception 'اكتبي عنوان الشحن'; end if;
  v_short := upper(regexp_replace(coalesce(p_shipping->>'shortAddress', ''), '[\s-]', '', 'g'));
  if v_short !~ '^[A-Z]{4}[0-9]{4}$' then raise exception 'العنوان الوطني المختصر غير صحيح (4 حروف و4 أرقام)'; end if;
  if btrim(coalesce(p_shipping->>'city', '')) = '' then raise exception 'اكتبي المدينة'; end if;
  if btrim(coalesce(p_shipping->>'district', '')) = '' then raise exception 'اكتبي الحي'; end if;
  v_ship := jsonb_build_object(
    'shortAddress', v_short,
    'city', left(btrim(p_shipping->>'city'), 60),
    'district', left(btrim(p_shipping->>'district'), 80),
    'street', left(btrim(coalesce(p_shipping->>'street', '')), 120),
    'details', left(btrim(coalesce(p_shipping->>'details', '')), 300));

  for v_line in select * from jsonb_array_elements(p_items) loop
    select * into v_p from public.products where id = v_line->>'product_id' and active;
    if not found then raise exception 'منتج غير متوفر: %', v_line->>'product_id'; end if;
    v_qty := greatest(1, least(999, coalesce((v_line->>'qty')::int, 1)));
    v_price := case when v_p.sale_price is not null and v_p.sale_price < v_p.price then v_p.sale_price else v_p.price end;

    -- options: only choices that exist on the product count; required ones must be chosen; "pick one" means one
    v_sel := array(select jsonb_array_elements_text(case when jsonb_typeof(v_line->'options') = 'array' then v_line->'options' else '[]'::jsonb end) limit 50);
    v_add := 0;
    v_chosen := '[]';
    for v_o in select * from jsonb_array_elements(coalesce(v_p.options, '[]'::jsonb)) loop
      v_n := 0;
      for v_v in select * from jsonb_array_elements(coalesce(v_o->'values', '[]'::jsonb)) loop
        if ((v_o->>'id') || ':' || (v_v->>'id')) = any(v_sel) then
          v_n := v_n + 1;
          v_add := v_add + greatest(0, coalesce((v_v->>'price')::numeric, 0));
          v_chosen := v_chosen || jsonb_build_object('option', v_o->>'name', 'value', v_v->>'name', 'price', greatest(0, coalesce((v_v->>'price')::numeric, 0)));
        end if;
      end loop;
      if coalesce((v_o->>'required')::boolean, false) and v_n = 0 then raise exception 'اختاري «%» في %', v_o->>'name', v_p.name; end if;
      if v_o->>'type' = 'radio' and v_n > 1 then raise exception 'اختيار واحد بس في «%»', v_o->>'name'; end if;
    end loop;
    v_price := v_price + v_add;

    v_sub := v_sub + v_price * v_qty;
    v_items := v_items || jsonb_build_object(
      'productId', v_p.id, 'name', v_p.name, 'price', v_price, 'qty', v_qty,
      'image', v_p.image, 'digital', v_p.digital, 'note', left(coalesce(v_line->>'note', ''), 500), 'options', v_chosen);
  end loop;

  if p_coupon is not null and p_coupon <> '' then
    -- one open checkout per account per code: an earlier unpaid order with the same code is cancelled
    -- (the release trigger gives its use back), so unpaid orders can't eat up a limited coupon
    update public.orders
       set status = 'cancelled',
           history = history || jsonb_build_array(jsonb_build_object('status', 'cancelled', 'at', now(), 'note', 'استُبدل بطلب أحدث بنفس كود الخصم'))
     where user_id = auth.uid() and status = 'pending' and coupon = upper(p_coupon);
    v_c := public.check_coupon(p_coupon);
    if v_c.code is null then raise exception 'الكود غير صالح أو منتهي'; end if;
    v_disc := least(v_sub, case when v_c.type = 'percent' then round(v_sub * least(v_c.value, 100) / 100, 2) else greatest(v_c.value, 0) end);
    -- count the use; a coupon with max_uses stops once it is used up
    update public.coupons set used = used + 1 where code = v_c.code and (max_uses is null or used < max_uses);
    if not found then raise exception 'كود الخصم انتهى عدد استخداماته'; end if;
  end if;

  v_fee := public.shipping_fee_for(v_sub);

  insert into public.orders (user_id, customer, items, subtotal, discount, coupon, total, notes, payment_method, history, terms_accepted_at, terms_version, shipping, shipping_fee)
  values (auth.uid(), p_customer, v_items, v_sub, v_disc, nullif(upper(p_coupon), ''), v_sub - v_disc + v_fee,
          left(coalesce(p_notes, ''), 2000), 'card',  -- payment is online only (Tap)
          jsonb_build_array(jsonb_build_object('status', 'pending', 'at', now())),
          now(), '2026-10',  -- checkout can't submit without accepting the terms (src/data/terms.js TERMS_VERSION)
          v_ship, v_fee)
  returning id into v_id;
  return v_id;
end $$;

revoke execute on function public.place_order(jsonb, jsonb, jsonb, text, text, text) from anon, public;
grant execute on function public.place_order(jsonb, jsonb, jsonb, text, text, text) to authenticated;
revoke execute on function public.shipping_fee_for(numeric) from anon, public;
grant execute on function public.shipping_fee_for(numeric) to authenticated;

